def list_tags(limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0516000" if __import__("os").path.isdir("./environment_mix/0516000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_tags"
    status = "ok"

    # --- Validate unexpected extra parameters (additionalProperties: false) ---
    if _extra:
        status = "validation_error"
        # Log call
        try:
            audit = _load("audit_log.json")
            if not isinstance(audit, list):
                audit = []
            audit.append({
                "ts": datetime.datetime.utcnow().isoformat() + "Z",
                "endpoint": endpoint,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "details": {"unexpected_params": sorted(list(_extra.keys()))}
            })
            _save("audit_log.json", audit)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "Unexpected parameters.", unexpected_params=sorted(list(_extra.keys())))

    # --- Validate inputs ---
    if limit is not None:
        if not isinstance(limit, int):
            status = "validation_error"
            try:
                audit = _load("audit_log.json")
                if not isinstance(audit, list):
                    audit = []
                audit.append({
                    "ts": datetime.datetime.utcnow().isoformat() + "Z",
                    "endpoint": endpoint,
                    "status": status,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "details": {"field": "limit"}
                })
                _save("audit_log.json", audit)
            except Exception:
                pass
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        if limit < 1:
            status = "validation_error"
            try:
                audit = _load("audit_log.json")
                if not isinstance(audit, list):
                    audit = []
                audit.append({
                    "ts": datetime.datetime.utcnow().isoformat() + "Z",
                    "endpoint": endpoint,
                    "status": status,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "details": {"field": "limit", "minimum": 1}
                })
                _save("audit_log.json", audit)
            except Exception:
                pass
            return _err("VALIDATION_ERROR", "limit must be >= 1.")

    if sort is not None and sort not in ("name", "tag_id"):
        status = "validation_error"
        try:
            audit = _load("audit_log.json")
            if not isinstance(audit, list):
                audit = []
            audit.append({
                "ts": datetime.datetime.utcnow().isoformat() + "Z",
                "endpoint": endpoint,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "details": {"field": "sort", "allowed": ["name", "tag_id"]}
            })
            _save("audit_log.json", audit)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "Unsupported sort field.", allowed=["name", "tag_id"])

    if order is not None and order not in ("asc", "desc"):
        status = "validation_error"
        try:
            audit = _load("audit_log.json")
            if not isinstance(audit, list):
                audit = []
            audit.append({
                "ts": datetime.datetime.utcnow().isoformat() + "Z",
                "endpoint": endpoint,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "details": {"field": "order", "allowed": ["asc", "desc"]}
            })
            _save("audit_log.json", audit)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "Unsupported order value.", allowed=["asc", "desc"])

    # --- Load and normalize tag rows ---
    raw = _load("tags.json")
    if isinstance(raw, dict) and "rows" in raw and isinstance(raw["rows"], list):
        tags = raw["rows"]
    elif isinstance(raw, list):
        tags = raw
    else:
        tags = []

    # Ensure tags are objects
    if any(not isinstance(t, dict) for t in tags):
        # tolerate but filter invalid rows
        tags = [t for t in tags if isinstance(t, dict)]

    # --- Apply sorting ---
    sort_field = sort or "tag_id"
    sort_order = order or "asc"
    reverse = (sort_order == "desc")

    def _key(t):
        v = t.get(sort_field)
        if v is None:
            return ""
        return str(v).lower() if sort_field == "name" else str(v)

    tags_sorted = sorted(tags, key=_key, reverse=reverse)

    # --- Cursor pagination ---
    # Cursor is opaque string we generate as: "idx:<offset>"
    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.startswith("idx:"):
            status = "validation_error"
            try:
                audit = _load("audit_log.json")
                if not isinstance(audit, list):
                    audit = []
                audit.append({
                    "ts": datetime.datetime.utcnow().isoformat() + "Z",
                    "endpoint": endpoint,
                    "status": status,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "details": {"field": "cursor"}
                })
                _save("audit_log.json", audit)
            except Exception:
                pass
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        try:
            start = int(cursor.split("idx:", 1)[1])
        except ValueError:
            status = "validation_error"
            try:
                audit = _load("audit_log.json")
                if not isinstance(audit, list):
                    audit = []
                audit.append({
                    "ts": datetime.datetime.utcnow().isoformat() + "Z",
                    "endpoint": endpoint,
                    "status": status,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "details": {"field": "cursor"}
                })
                _save("audit_log.json", audit)
            except Exception:
                pass
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        if start < 0 or start > len(tags_sorted):
            status = "validation_error"
            try:
                audit = _load("audit_log.json")
                if not isinstance(audit, list):
                    audit = []
                audit.append({
                    "ts": datetime.datetime.utcnow().isoformat() + "Z",
                    "endpoint": endpoint,
                    "status": status,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "details": {"field": "cursor", "reason": "out_of_range"}
                })
                _save("audit_log.json", audit)
            except Exception:
                pass
            return _err("VALIDATION_ERROR", "Cursor is invalid or no longer usable.")

    page_limit = limit if limit is not None else 50
    page = tags_sorted[start:start + page_limit]
    next_idx = start + len(page)
    has_more = next_idx < len(tags_sorted)
    next_cursor = f"idx:{next_idx}" if has_more else None

    # --- Record usage/audit for EVERY call ---
    try:
        audit = _load("audit_log.json")
        if not isinstance(audit, list):
            audit = []
        audit.append({
            "ts": datetime.datetime.utcnow().isoformat() + "Z",
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "details": {"limit": limit, "cursor": cursor, "sort": sort, "order": order}
        })
        _save("audit_log.json", audit)
    except Exception:
        pass

    return {
        "data": page,
        "meta": {
            "total": len(tags_sorted),
            "limit": page_limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort_field,
            "order": sort_order,
        },
    }

