def kb_search(query, limit=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0516000" if __import__("os").path.isdir("./environment_mix/0516000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "kb_search"
    status = "ok"

    # Validate required query
    if not isinstance(query, str) or not query.strip():
        status = "validation_error"
        try:
            audit = _load("audit_log.json")
            if not isinstance(audit, list):
                audit = []
            audit.append({
                "ts": datetime.datetime.utcnow().isoformat() + "Z",
                "endpoint": endpoint,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "details": {"field": "query"}
            })
            _save("audit_log.json", audit)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "query must be a non-empty string.")

    if limit is not None:
        if not isinstance(limit, int):
            status = "validation_error"
            try:
                audit = _load("audit_log.json")
                if not isinstance(audit, list):
                    audit = []
                audit.append({
                    "ts": datetime.datetime.utcnow().isoformat() + "Z",
                    "endpoint": endpoint,
                    "status": status,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "details": {"field": "limit"}
                })
                _save("audit_log.json", audit)
            except Exception:
                pass
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        if limit < 1 or limit > 200:
            status = "validation_error"
            try:
                audit = _load("audit_log.json")
                if not isinstance(audit, list):
                    audit = []
                audit.append({
                    "ts": datetime.datetime.utcnow().isoformat() + "Z",
                    "endpoint": endpoint,
                    "status": status,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "details": {"field": "limit", "allowed_range": [1, 200]}
                })
                _save("audit_log.json", audit)
            except Exception:
                pass
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200.", allowed_range=[1, 200])

    raw = _load("articles.json")
    if isinstance(raw, dict) and "rows" in raw and isinstance(raw["rows"], list):
        articles = raw["rows"]
    elif isinstance(raw, list):
        articles = raw
    else:
        articles = []

    q = query.casefold()
    hits = []
    for a in articles:
        if not isinstance(a, dict):
            continue
        title = str(a.get("title", "") or "")
        body = str(a.get("body", "") or "")
        if q in title.casefold() or q in body.casefold():
            hits.append(a)

    # deterministic ordering: most viewed first, then article_id
    def _k(a):
        v = a.get("views")
        try:
            v = int(v)
        except Exception:
            v = 0
        return (-v, str(a.get("article_id", "")))

    hits = sorted(hits, key=_k)
    if limit is not None:
        hits = hits[:limit]

    try:
        audit = _load("audit_log.json")
        if not isinstance(audit, list):
            audit = []
        audit.append({
            "ts": datetime.datetime.utcnow().isoformat() + "Z",
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "details": {"query_len": len(query), "limit": limit, "results": len(hits)}
        })
        _save("audit_log.json", audit)
    except Exception:
        pass

    return {
        "data": hits,
        "meta": {"count": len(hits), "limit": limit}
    }

def kb_update_article(article_id, title=None, body=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0516000" if __import__("os").path.isdir("./environment_mix/0516000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "kb_update_article"
    status = "ok"

    # Validate required article_id
    if not isinstance(article_id, str) or not article_id.strip():
        status = "validation_error"
        try:
            audit = _load("audit_log.json")
            if not isinstance(audit, list):
                audit = []
            audit.append({
                "ts": datetime.datetime.utcnow().isoformat() + "Z",
                "endpoint": endpoint,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "details": {"field": "article_id"}
            })
            _save("audit_log.json", audit)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "article_id must be a non-empty string.")

    # Must provide at least one of title/body
    if title is None and body is None:
        status = "validation_error"
        try:
            audit = _load("audit_log.json")
            if not isinstance(audit, list):
                audit = []
            audit.append({
                "ts": datetime.datetime.utcnow().isoformat() + "Z",
                "endpoint": endpoint,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "details": {"reason": "no_changes"}
            })
            _save("audit_log.json", audit)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "At least one of title or body must be provided.")

    if title is not None and not isinstance(title, str):
        status = "validation_error"
        try:
            audit = _load("audit_log.json")
            if not isinstance(audit, list):
                audit = []
            audit.append({
                "ts": datetime.datetime.utcnow().isoformat() + "Z",
                "endpoint": endpoint,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "details": {"field": "title"}
            })
            _save("audit_log.json", audit)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "title must be a string.")

    if body is not None and not isinstance(body, str):
        status = "validation_error"
        try:
            audit = _load("audit_log.json")
            if not isinstance(audit, list):
                audit = []
            audit.append({
                "ts": datetime.datetime.utcnow().isoformat() + "Z",
                "endpoint": endpoint,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "details": {"field": "body"}
            })
            _save("audit_log.json", audit)
        except Exception:
            pass
        return _err("VALIDATION_ERROR", "body must be a string.")

    raw = _load("articles.json")
    container_is_dict = isinstance(raw, dict)
    if container_is_dict and "rows" in raw and isinstance(raw["rows"], list):
        articles = raw["rows"]
    elif isinstance(raw, list):
        articles = raw
        container_is_dict = False
    else:
        articles = []
        container_is_dict = False

    idx = None
    for i, a in enumerate(articles):
        if isinstance(a, dict) and a.get("article_id") == article_id:
            idx = i
            break

    if idx is None:
        status = "not_found"
        try:
            audit = _load("audit_log.json")
            if not isinstance(audit, list):
                audit = []
            audit.append({
                "ts": datetime.datetime.utcnow().isoformat() + "Z",
                "endpoint": endpoint,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "details": {"article_id": article_id}
            })
            _save("audit_log.json", audit)
        except Exception:
            pass
        return _err("NOT_FOUND", "Unknown article_id.", article_id=article_id)

    existing = articles[idx]
    if not isinstance(existing, dict):
        status = "not_found"
        try:
            audit = _load("audit_log.json")
            if not isinstance(audit, list):
                audit = []
            audit.append({
                "ts": datetime.datetime.utcnow().isoformat() + "Z",
                "endpoint": endpoint,
                "status": "not_found",
                "latency_ms": int((time.time() - t0) * 1000),
                "details": {"article_id": article_id, "reason": "corrupt_row"}
            })
            _save("audit_log.json", audit)
        except Exception:
            pass
        return _err("NOT_FOUND", "Unknown article_id.", article_id=article_id)

    updated = dict(existing)
    changed = False
    if title is not None and title != updated.get("title"):
        updated["title"] = title
        changed = True
    if body is not None and body != updated.get("body"):
        updated["body"] = body
        changed = True

    if not changed:
        # Idempotent no-op update still returns the record, but should not claim to have changed storage.
        # However the tool is "updates ... and returns updated article"; it's acceptable to persist unchanged.
        # We'll persist unchanged to keep observable write semantics.
        pass

    articles[idx] = updated

    # Persist back exactly to file
    try:
        if container_is_dict:
            raw["rows"] = articles
            _save("articles.json", raw)
        else:
            _save("articles.json", articles)
    except Exception:
        status = "conflict"
        try:
            audit = _load("audit_log.json")
            if not isinstance(audit, list):
                audit = []
            audit.append({
                "ts": datetime.datetime.utcnow().isoformat() + "Z",
                "endpoint": endpoint,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "details": {"article_id": article_id}
            })
            _save("audit_log.json", audit)
        except Exception:
            pass
        return _err("CONFLICT", "Failed to persist update.")

    try:
        audit = _load("audit_log.json")
        if not isinstance(audit, list):
            audit = []
        audit.append({
            "ts": datetime.datetime.utcnow().isoformat() + "Z",
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "details": {"article_id": article_id, "changed": bool(changed)}
        })
        _save("audit_log.json", audit)
    except Exception:
        pass

    return {"data": updated}
